## 2. Lógica de Leitura e Parsing do `patch.lua`

O formato Lua não é JSON ou XML, é um script. Precisamos de um parser. Para arquivos pequenos e estruturados como este, um parser simples baseado em regex ou manipulação de string é o mais prático, embora seja frágil. **Para um projeto robusto, eu recomendaria usar uma biblioteca de parsing Lua, mas farei uma versão simplificada aqui.**

**`Services/PatchService.cs` (Parte do Parsing)**

```csharp
using System.IO;
using System.Text.RegularExpressions;
using System.Collections.Generic;
using System.Linq;

public class PatchService
{
    private const string LuaFilePath = "patch.lua";

    // Este método simplificado pressupõe que o formato é sempre o mesmo.
    public List<PatchItem> LoadPatchManifest()
    {
        if (!File.Exists(LuaFilePath))
        {
            throw new FileNotFoundException($"Arquivo de manifesto não encontrado: {LuaFilePath}");
        }

        string content = File.ReadAllText(LuaFilePath);
        var items = new List<PatchItem>();

        // Regex para capturar cada bloco de item: { Version = X, FileName = "Y", Integrity= "Z" }
        // Isso é muito específico para o seu formato.
        var itemRegex = new Regex(@"\{ Version\s*=\s*(\d+),\s*FileName\s*=\s*""([^""]+)""\s*,\s*Integrity\s*=\s*""([^""]+)"" \}");

        foreach (Match match in itemRegex.Matches(content))
        {
            items.Add(new PatchItem
            {
                Version = int.Parse(match.Groups[1].Value),
                FileName = match.Groups[2].Value,
                Integrity = match.Groups[3].Value
            });
        }

        return items;
    }
}
```

## 3. Lógica de Download e Gerenciamento de Estado (Serviço Principal)

Este é o coração da aplicação, onde a mágica do download, reconexão e verificação acontece. Usaremos `HttpClient` para os downloads.

**`Services/DownloadManagerService.cs`**

```csharp
using System.IO;
using System.Net.Http;
using System.Threading.Tasks;
using System.Collections.Generic;
using System.Security.Cryptography;
using System.Text;
using System.Linq;
using System;

public class DownloadManagerService
{
    private readonly HttpClient _httpClient;
    private readonly PatchService _patchService;
    private readonly string _downloadDirectory;

    private List<PatchItem> _manifest;
    private int _currentIndex = 0;
    private bool _isRunning = false;

    public event Action<string> StatusUpdate;
    public event Action<double> ProgressUpdate;
    public event Action<PatchItem> CurrentFileUpdate;

    public DownloadManagerService(PatchService patchService)
    {
        _patchService = patchService;
        _httpClient = new HttpClient();

        // Define o diretório de destino: Pasta do executável/aplicação
        // Ajuste esta linha dependendo de onde seu aplicativo roda (e.g., Blazor WebAssembly vs Server)
        _downloadDirectory = Path.Combine(AppDomain.CurrentDomain.BaseDirectory, "patch"); 

        // Garante que o diretório exista
        if (!Directory.Exists(_downloadDirectory))
        {
            Directory.CreateDirectory(_downloadDirectory);
        }
    }

    public async Task StartDownloadAsync()
    {
        if (_isRunning) return;
        _isRunning = true;

        try
        {
            // 1. Conectar e Obter Manifesto
            StatusUpdate?.Invoke("Conectando ao servidor...");
            _manifest = _patchService.LoadPatchManifest();

            // 2. Autenticação (Simulado)
            await Task.Delay(1000); // Simula chamada de autenticação
            StatusUpdate?.Invoke("Autenticação do servidor realizada com sucesso.");

            StatusUpdate?.Invoke("Preparando para iniciar o download...");

            // Inicia o loop principal de download
            await ProcessDownloadsAsync();
        }
        catch (FileNotFoundException ex)
        {
            StatusUpdate?.Invoke($"Erro crítico: {ex.Message}");
            _isRunning = false;
        }
        catch (HttpRequestException ex) when (ex.Message.Contains("404"))
        {
            // 3. Arquivo não encontrado (se fosse um único arquivo)
            StatusUpdate?.Invoke("Erro: Arquivo não encontrado (404). Saltando em 5 segundos...");
            await Task.Delay(5000); 
            // Lógica de saltar seria complexa aqui, mas demonstra o conceito.
        }
        catch (Exception ex)
        {
            StatusUpdate?.Invoke($"Erro fatal durante o processo: {ex.Message}");
        }
        finally
        {
            _isRunning = false;
            StatusUpdate?.Invoke("Processo de download finalizado.");
        }
    }

    private async Task ProcessDownloadsAsync()
    {
        while (_currentIndex < _manifest.Count && _isRunning)
        {
            var item = _manifest[_currentIndex];
            var targetPath = Path.Combine(_downloadDirectory, item.FileName);

            // 5. Checa se o arquivo já existe
            if (File.Exists(targetPath))
            {
